namespace MobileWrapper.Scripts
{
    public static class IOSScripts
    {
        public static string iOSGetCredentialsScript = "(function(){function getElementByXPath(xpath){return document.evaluate(xpath,document,null,XPathResult.FIRST_ORDERED_NODE_TYPE,null).singleNodeValue;}const interval=setInterval(()=>{const emailInput=getElementByXPath(\"//input[@id='Input_Email']\");const passwordInput=getElementByXPath(\"//input[@id='Input_Password']\");const loginButton=getElementByXPath(\"//button[@id='login-submit']\");if(emailInput&&passwordInput&&loginButton&&!loginButton._handlerAttached){clearInterval(interval);loginButton._handlerAttached=true;loginButton.addEventListener('click',function(e){const currentUsernameValue=emailInput.value;const currentPwdValue=passwordInput.value;var formData={function:'retrieveCredentials',data:currentUsernameValue+','+currentPwdValue};invokeCSharpAction(JSON.stringify(formData));});console.log('Login button handler attached!');}else{console.log('Waiting for login elements...');}},500);})();";
        public static string iOSPdfShareScript = @"(function(){function getElementByXPath(xpath){return document.evaluate(xpath,document,null,XPathResult.FIRST_ORDERED_NODE_TYPE,null).singleNodeValue;}const interval=setInterval(()=>{const pdfLink=getElementByXPath('//a[contains(@href, "".pdf"")]');if(pdfLink){clearInterval(interval);pdfLink.addEventListener('click',function(e){e.preventDefault();const pdfUrl=new URL(pdfLink.getAttribute('href'),window.location.origin).href;var formData={function:'openPdf',data:pdfUrl};invokeCSharpAction(JSON.stringify(formData));});console.log('PDF link click interception attached!');}else{console.log('Waiting for PDF link...');}},500);})();";


        public static string iOSPrintPageScript = @"var iPrint = 0; var intervalPrint = setInterval(function () { var print_button = document.querySelector('#printButton'); console.log('Found:', print_button); if (document.readyState === 'complete' && print_button != null) { clearInterval(intervalPrint); print_button.replaceWith(print_button.cloneNode(true)); print_button = document.querySelector('#printButton'); print_button.addEventListener('click', function (event) { event.preventDefault(); var formData = { function: 'printPrivacy', data: '' }; var jsonConvertedData = JSON.stringify(formData); invokeCSharpAction(jsonConvertedData); }); console.log('✅ Print button handler attached.'); } if (iPrint >= 20) { clearInterval(intervalPrint); console.log('⏱️ Timeout: print button not found.'); } iPrint = iPrint + 1; }, 500);";

        public static string iOSReinforceTelephoneScript = @"var interval = setInterval(() => { var phoneInput = document.getElementById('user-phone-number'); if (phoneInput) { clearInterval(interval); phoneInput.type = 'tel'; phoneInput.setAttribute('inputmode', 'tel'); } }, 500);";
        public static string iOSGetLocationScript = @"setInterval(() => { if (document.readyState === 'complete') { navigator.geolocation.getCurrentPosition = function(successCallback, errorCallback) { try { const callbackId = 'cb_' + Date.now(); window._geoCallbacks = window._geoCallbacks || {}; window._geoCallbacks[callbackId] = { successCallback, errorCallback }; var formData = { function:'getLocation' }; invokeCSharpAction(JSON.stringify(formData)); } catch (error) { if (typeof errorCallback === 'function') { errorCallback({ code: 1, message: error.message }); } } }; } }, 300);";
    }
}
